Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(pub)-[:FROM_CHUNK]-(unused:Chunk)
WITH DISTINCT a, pub
MATCH (a)-[:FROM_CHUNK]->(c:Chunk)
WHERE (
  (toLower(a.name) CONTAINS 'when pop culture and sport collide: a timeline of taylor swift’s nfl takeover'
    AND (toLower(pub.name) CONTAINS 'the age' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'the age')))
  OR
  (toLower(a.name) CONTAINS 'taylor swift-travis kelce timeline'
    AND (toLower(pub.name) CONTAINS 'cbsports.com' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'cbsports.com')))
  OR
  (toLower(a.name) CONTAINS 'taylor swift reveals secret start to her relationship with travis kelce'
    AND (toLower(pub.name) CONTAINS 'the independent - life and style' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'the independent - life and style')))
)
OPTIONAL MATCH (a)-[r:MENTIONS|PARTICIPATED_IN|SAID]->(e:__Entity__)
WHERE type(r) = 'SAID'
  OR toLower(e.name) CONTAINS 'taylor swift'
  OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'taylor swift')
  OR toLower(e.name) CONTAINS 'travis kelce'
  OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'travis kelce')
  OR toLower(e.name) CONTAINS 'arrowhead stadium'
  OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'arrowhead stadium')
RETURN a.name AS article, pub.name AS publisher, c.text AS passage, type(r) AS connection, e.name AS connected_entity
LIMIT 10
Rows returned (at most 10): 10
