Cypher query: MATCH (a:Article)
WHERE
  (
    (toLower(a.name) CONTAINS 'google' OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'google'))
    AND (
      toLower(a.name) CONTAINS 'publisher' OR toLower(a.name) CONTAINS 'payment' OR toLower(a.name) CONTAINS 'news'
      OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'publisher' OR toLower(alias) CONTAINS 'payment' OR toLower(alias) CONTAINS 'news')
    )
  )
  OR toLower(a.name) CONTAINS 'is google search better than the rest'
  OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'is google search better than the rest')
  OR toLower(a.name) CONTAINS 'sam altman backs teens'
  OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'sam altman backs teens')
OPTIONAL MATCH (a)-[r:MENTIONS|PUBLISHED_BY|PART_OF]->(e:__Entity__)
RETURN a.name AS article, type(r) AS relationship, e.name AS connected_entity
LIMIT 10
