OPTIONAL MATCH (a)-[mentionRel:MENTIONS]->(e:__Entity__)
OPTIONAL MATCH (a)-[:FROM_CHUNK]->(c:Chunk)-[:FROM_DOCUMENT]->(d:Document)
WHERE toLower(a.name) CONTAINS "how u.s. women’s soccer team lured emma hayes away from chelsea"
   OR (
     (toLower(p.name) CONTAINS "the new york times"
       OR toLower(p.name) CONTAINS "the guardian"
       OR toLower(p.name) CONTAINS "sky sports"
       OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS "the new york times" OR toLower(alias) CONTAINS "the guardian" OR toLower(alias) CONTAINS "sky sports"))
     AND e IS NOT NULL
     AND (toLower(e.name) CONTAINS "chelsea"
       OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS "chelsea")
       OR toLower(e.name) CONTAINS "todd boehly"
       OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS "todd boehly"))
   )
RETURN a.name AS article, p.name AS publisher, type(pubRel) AS publisher_relationship,
       e.name AS mentioned_entity, type(mentionRel) AS mention_relationship,
